function el(id){return document.getElementById(id);}function q(sel,root){return(root||document).querySelector(sel);}function qa(sel,root){return(root||document).querySelectorAll(sel);}function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function icon(name,cls){return '<svg class="'+(cls||'icon')+'"><use href="#i-'+name+'" xlink:href="#i-'+name+'"></use></svg>';}
function faNum(v){var s=String(v==null?'':v),m='۰۱۲۳۴۵۶۷۸۹';return s.replace(/[0-9]/g,function(x){return m.charAt(Number(x));});}
function g2j(gy,gm,gd){var gdm=[0,31,59,90,120,151,181,212,243,273,304,334],jy,days,jm,jd,gy2;if(gy>1600){jy=979;gy-=1600;}else{jy=0;gy-=621;}gy2=gm>2?gy+1:gy;days=365*gy+Math.floor((gy2+3)/4)-Math.floor((gy2+99)/100)+Math.floor((gy2+399)/400)-80+gd+gdm[gm-1];jy+=33*Math.floor(days/12053);days%=12053;jy+=4*Math.floor(days/1461);days%=1461;if(days>365){jy+=Math.floor((days-1)/365);days=(days-1)%365;}if(days<186){jm=1+Math.floor(days/31);jd=1+(days%31);}else{jm=7+Math.floor((days-186)/30);jd=1+((days-186)%30);}return{jy:jy,jm:jm,jd:jd};}
function shamsiParts(iso){var m=String(iso||'').match(/^(\d{4})-(\d{2})-(\d{2})/);if(!m)return null;var g={y:Number(m[1]),m:Number(m[2]),d:Number(m[3])},j=g2j(g.y,g.m,g.d),dt=new Date(g.y,g.m-1,g.d,12,0,0);return{year:j.jy,month:j.jm,day:j.jd,weekday:dt.getDay()};}
function shamsiDate(iso,withWeekday){var p=shamsiParts(iso);if(!p)return String(iso||'');var months=['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'],days=['یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه','شنبه'];return (withWeekday?days[p.weekday]+' ':'')+faNum(p.day)+' '+months[p.month-1]+' '+faNum(p.year);}
function shamsiDateTime(v){if(!v)return'—';var raw=String(v),date=raw.slice(0,10),time='';var tm=raw.match(/T(\d{2}):(\d{2})/);if(tm)time=faNum(tm[1]+':'+tm[2]);return shamsiDate(date,false)+(time?'، '+time:'');}
function isoToday(){var d=new Date(),y=d.getFullYear(),m=('0'+(d.getMonth()+1)).slice(-2),day=('0'+d.getDate()).slice(-2);return y+'-'+m+'-'+day;}
function shiftDate(iso,days){var d=new Date(iso+'T12:00:00');d.setDate(d.getDate()+days);return d.getFullYear()+'-'+('0'+(d.getMonth()+1)).slice(-2)+'-'+('0'+d.getDate()).slice(-2);}
function hhmm(){var d=new Date();return('0'+d.getHours()).slice(-2)+':'+('0'+d.getMinutes()).slice(-2);}
function plannedMinutes(task){if(!task)return 0;var a=task.start.split(':'),b=task.end.split(':');return Math.max(0,(+b[0]*60 + +b[1])-(+a[0]*60 + +a[1]));}
function toast(msg,type){var stack=el('toastStack');if(!stack)return;var card=document.createElement('div'),kind=type||((/خطا|نشد|نامعتبر|نیست/.test(String(msg)))?'error':'success');card.className='toast-card '+kind;card.innerHTML='<span class="toast-icon">'+icon(kind==='error'?'alert':'check2')+'</span><div><strong>'+(kind==='error'?'نیاز به توجه':'انجام شد')+'</strong><p>'+esc(msg)+'</p></div>';stack.appendChild(card);setTimeout(function(){card.classList.add('leaving');setTimeout(function(){if(card.parentNode)card.parentNode.removeChild(card);},220);},3600);}
