function hasPendingLogout(){try{return sessionStorage.getItem('moshaver_logout_pending')==='1';}catch(e){return false;}}
function setPendingLogout(value){try{if(value)sessionStorage.setItem('moshaver_logout_pending','1');else sessionStorage.removeItem('moshaver_logout_pending');}catch(e){}}
function broadcastAuth(kind){try{localStorage.setItem(AUTH_SIGNAL_KEY,JSON.stringify({kind:kind,at:Date.now()}));}catch(e){}}
function finishLocalLogout(message,keepPending,skipBroadcast){
  state.authStatus='anonymous';state.authEpoch++;state.bootEpoch++;
  API.clearAuth();API.abortAll();stopPresence();disconnectEvents();stopSessionClock();resetAuthenticatedState();
  if(!keepPending)setPendingLogout(false);
  el('loginPassword').value='';
  showLogin(message||'با موفقیت خارج شدید.');
  if(!skipBroadcast)broadcastAuth('logout');
}
function handleAuthFailure(err){
  if(state.authStatus!=='authenticated')return;
  setPendingLogout(false);
  finishLocalLogout((err&&err.message)||'نشست شما پایان یافته است. دوباره وارد شوید.',false,false);
}
function flushPendingLogout(done){
  if(!hasPendingLogout()){if(done)done(null);return;}
  API.request('POST','/auth/logout',{},function(err){
    if(err&&err.status===0){if(done)done(err);return;}
    setPendingLogout(false);API.clearAuth();if(done)done(null);
  },{suppressAuthFailure:true,noCsrfRetry:true});
}
function clearWrongRoleSession(message){
  state.authStatus='logging-out';setPendingLogout(true);
  API.request('POST','/auth/logout',{},function(err){
    finishLocalLogout(message,!!(err&&err.status===0),false);
  },{suppressAuthFailure:true,noCsrfRetry:true});
}
