function deviceLabel(){var ua=navigator.userAgent||'';if(/Android/i.test(ua))return 'Android';if(/iPhone|iPad/i.test(ua))return 'iOS';return 'Web';}
function startPresence(){stopPresence();sendPresence();state.presenceTicker=setInterval(sendPresence,45000);}
function stopPresence(){if(state.presenceTicker)clearInterval(state.presenceTicker);state.presenceTicker=null;if(state.sessionHeartbeat)clearInterval(state.sessionHeartbeat);state.sessionHeartbeat=null;}
