function loadMe(done){var epoch=++state.authEpoch;state.authStatus='checking';state.startupAuthRequest=API.request('GET','/auth/me',null,function(err,data){state.startupAuthRequest=null;if(epoch!==state.authEpoch)return;if(err){if(err.status===401)state.authStatus='anonymous';else state.authStatus='checking';return done&&done(err);}if(!data||data.role!=='student'){clearWrongRoleSession('این حساب دانش‌آموز نیست.');return done&&done({status:403,message:'این حساب دانش‌آموز نیست.',handled:true});}state.me=data;state.authStatus='authenticated';done&&done(null,data);},{suppressAuthFailure:true});}
