function renderToday(){var d=state.dashboard||{},plan=d.plan,metrics=d.planMetrics||{};el('todayPersian').textContent=plan&&plan.persianDate?plan.persianDate:shamsiDate(isoToday(),true);el('planTitle').textContent=plan&&plan.title?plan.title:'فعالیت‌های امروز';renderMotivation(plan);el('metricTasks').textContent=faNum((metrics.doneTasks||0)+(metrics.partialTasks||0))+'/'+faNum(metrics.totalTasks||0);var pct=metrics.totalTasks?Math.round(((metrics.doneTasks||0)+(metrics.partialTasks||0)*.5)*100/metrics.totalTasks):0;el('metricTasksBar').style.width=pct+'%';el('metricMinutes').textContent=faNum(metrics.actualMinutes||0)+' دقیقه';el('plannedMinutes').textContent='از '+faNum(metrics.plannedMinutes||0)+' دقیقه';el('metricTests').textContent=faNum(metrics.actualTests||0);el('plannedTests').textContent='هدف '+faNum(metrics.plannedTests||0);renderCurrent();renderTimeline(plan?plan.tasks:[],'todayTimeline');renderExamFocus(d.nextExam);}
function renderMotivation(plan){var box=el('motivationCard'),text=plan&&plan.motivationText?String(plan.motivationText).replace(/^\s+|\s+$/g,''):'';if(!box)return;if(!text){box.className='daily-motivation hidden';return;}el('motivationText').textContent=text;box.className='daily-motivation';}
function statusForTask(t,nowTime){if(t.completion)return t.completion.status==='done'?'done':(t.completion.status==='partial'?'partial':'skipped');if(t.start<=nowTime&&nowTime<t.end)return'current';if(t.end<=nowTime)return'overdue';return'next';}
function getCurrentAndNext(tasks){var nowT=hhmm(),cur=null,next=null;for(var i=0;i<tasks.length;i++){var t=tasks[i];if(t.completion)continue;if(t.start<=nowT&&nowT<t.end){cur=t;break;}if(!next&&t.start>nowT)next=t;}if(!cur&&state.activeSession){for(i=0;i<tasks.length;i++)if(tasks[i].id===state.activeSession.taskId){cur=tasks[i];break;}}return{current:cur,next:next};}
function renderCurrent(){var tasks=state.plan&&state.plan.tasks?state.plan.tasks:[],cn=getCurrentAndNext(tasks);state.currentTask=cn.current;el('nowTime').textContent=hhmm();if(!cn.current){el('nowEmpty').className='empty-now';el('nowTask').className='hidden';}else{var t=cn.current;el('nowEmpty').className='empty-now hidden';el('nowTask').className='';el('nowSubject').textContent=t.subject||typeLabels[t.type]||'فعالیت';el('nowTitle').textContent=t.title||typeLabels[t.type]||'فعالیت';el('nowTypeIcon').innerHTML=icon(typeIcons[t.type]||'book');var meta='<span>'+esc(t.start)+' تا '+esc(t.end)+'</span>';if(t.pages)meta+='<span>صفحه '+esc(t.pages)+'</span>';if(t.testCount)meta+='<span>'+faNum(t.testCount)+' تست</span>';el('nowMeta').innerHTML=meta;if(t.type==='exam'&&t.examId)el('startNowBtn').innerHTML=icon('test')+'<span>باز کردن آزمون</span>';else el('startNowBtn').innerHTML=state.activeSession&&state.activeSession.taskId===t.id?icon('check')+'<span>پایان مطالعه</span>':icon('play')+'<span>شروع مطالعه</span>';}
if(cn.next){el('nextStrip').className='next-strip';el('nextTitle').textContent=(cn.next.subject?cn.next.subject+' — ':'')+(cn.next.title||'فعالیت');el('nextTime').textContent=cn.next.start;}else el('nextStrip').className='next-strip hidden';}
function taskCardHtml(t){var status=statusForTask(t,hhmm()),label={done:'انجام شده',partial:'نیمه‌کاره',skipped:'رد شده',current:'الان',overdue:'نیازمند تصمیم',next:'بعدی'}[status]||'';var cls=status==='partial'?'done':status,examCta=(t.type==='exam'&&t.examId&&!t.completion)?'<button class="timeline-exam-btn" data-task-exam="'+esc(t.examId)+'">'+icon('test')+'<span>باز کردن آزمون</span></button>':'';var details=(t.pages?'صفحه '+t.pages:'')+(t.testCount?(t.pages?' • ':'')+faNum(t.testCount)+' تست':'')+(t.note?((t.pages||t.testCount)?' • ':'')+t.note:'');return '<div class="timeline-item" data-task="'+esc(t.id)+'"><div class="timeline-time">'+faNum(t.start)+'</div><div class="timeline-card '+cls+(t.type==='exam'?' exam-task-card':'')+'"><div class="timeline-card-top"><span class="status-chip">'+label+'</span><span class="task-kind">'+esc(typeLabels[t.type]||'فعالیت')+'</span></div><div class="timeline-main"><span class="round-icon">'+icon(typeIcons[t.type]||'book')+'</span><div class="timeline-copy"><h4>'+esc((t.subject?t.subject+' — ':'')+(t.title||typeLabels[t.type]||'فعالیت'))+'</h4>'+(details?'<p>'+esc(details)+'</p>':'')+'</div></div>'+examCta+'</div></div>';}
function renderTimeline(tasks,target){var box=el(target);if(!tasks||!tasks.length){box.innerHTML='<div class="empty-card">برای این روز برنامه‌ای منتشر نشده است.</div>';return;}var html='';for(var i=0;i<tasks.length;i++)html+=taskCardHtml(tasks[i]);box.innerHTML=html;var cards=qa('[data-task]',box);for(i=0;i<cards.length;i++)cards[i].onclick=function(){var t=findTask(this.getAttribute('data-task'),tasks);if(t&&t.type==='exam'&&t.examId){openExam({id:t.examId});return;}openTask(t);};var examBtns=qa('[data-task-exam]',box);for(i=0;i<examBtns.length;i++)examBtns[i].onclick=function(e){if(e){e.preventDefault();e.stopPropagation();}openExam({id:this.getAttribute('data-task-exam')});};}
