function completeTask(t,status){var mins=state.activeSession&&state.activeSession.taskId===t.id?Math.round((Date.now()-new Date(state.activeSession.startedAt).getTime())/60000):plannedMinutes(t);queued('PUT','/tasks/'+encodeURIComponent(t.id)+'/completion',{status:status,actualMinutes:mins,actualTests:status==='done'?Number(t.testCount||0):0,note:''},function(err){if(err)return toast(err.message);if(state.activeSession&&state.activeSession.taskId===t.id)finishStudy(true);else{closeModals();toast(status==='done'?'ثبت شد ✓':'نیمه‌کاره ثبت شد');loadDashboard();}});}
function showFocus(t){if(!t)return;el('focusSubject').textContent=t.subject||typeLabels[t.type]||'مطالعه';el('focusTitle').textContent=t.title||'';var g='';if(t.pages)g+='<span>صفحه '+esc(t.pages)+'</span>';if(t.testCount)g+='<span>'+faNum(t.testCount)+' تست</span>';g+='<span>'+esc(t.start)+' تا '+esc(t.end)+'</span>';el('focusGoal').innerHTML=g;el('focusMode').className='focus-mode';}
