function startStudy(t){if(!t||state.sessionActionBusy)return;state.sessionActionBusy=true;api('POST','/study-sessions/start',{taskId:t.id,deviceLabel:deviceLabel()},function(err,data){state.sessionActionBusy=false;if(err){if(err.code==='ACTIVE_STUDY_SESSION'){restoreSession();toast('یک جلسه مطالعه دیگر فعال است؛ ابتدا همان را تمام کن.');return;}return toast(err.message);}state.activeSession=data;closeModals();startSessionClock();renderCurrent();showFocus(t);toast('مطالعه شروع شد');});}
function restoreSession(){api('GET','/study-sessions/active',null,function(err,data){if(err)return;state.activeSession=data||null;if(data){startSessionClock();var ft=findTask(data.taskId);if(ft)showFocus(ft);}else{stopSessionClock();hideFocus();}renderCurrent();});}
function startSessionClock(){stopSessionClock();if(!state.activeSession)return;el('activeTimer').className='active-timer';updateTimer();state.timerTicker=setInterval(updateTimer,1000);state.sessionHeartbeat=setInterval(function(){if(!state.activeSession)return;api('POST','/study-sessions/'+state.activeSession.id+'/heartbeat',{deviceLabel:deviceLabel()},function(){});},45000);}
