function updateTimer(){if(!state.activeSession)return;var sec=Math.max(0,Math.floor((Date.now()-new Date(state.activeSession.startedAt).getTime())/1000)),h=Math.floor(sec/3600),m=Math.floor(sec%3600/60),s=sec%60;var txt=('0'+h).slice(-2)+':'+('0'+m).slice(-2)+':'+('0'+s).slice(-2);el('timerDisplay').textContent=txt;if(el('focusTimer'))el('focusTimer').textContent=txt;}
function finishStudy(silent){if(!state.activeSession||state.sessionActionBusy)return;var id=state.activeSession.id;state.sessionActionBusy=true;api('POST','/study-sessions/'+id+'/finish',{deviceLabel:deviceLabel()},function(err,data){state.sessionActionBusy=false;if(err){if(err.status===404){state.activeSession=null;stopSessionClock();hideFocus();loadDashboard();return;}return toast(err.message);}state.activeSession=null;stopSessionClock();hideFocus();closeModals();if(!silent)toast('جلسه با '+faNum(data.actualMinutes)+' دقیقه ثبت شد');loadDashboard();});}
function openIssue(t){state.selectedTask=t;state.selectedIssueType='';var h='';for(var i=0;i<issueTypes.length;i++)h+='<button class="choice-btn" data-issue="'+esc(issueTypes[i])+'">'+esc(issueTypes[i])+'</button>';el('issueChoices').innerHTML=h;el('issueNote').value='';closeModals();openModal('issueModal');var bs=qa('[data-issue]',el('issueChoices'));for(i=0;i<bs.length;i++)bs[i].onclick=function(){var all=qa('[data-issue]',el('issueChoices'));for(var j=0;j<all.length;j++)all[j].classList.remove('active');this.classList.add('active');state.selectedIssueType=this.getAttribute('data-issue');};}
