function renderExamFocus(e){var box=el('examFocus');if(!e){box.className='exam-focus hidden';return;}box.className='exam-focus';el('examFocusTitle').textContent=e.title;var days=Math.ceil((new Date(e.isoDate+'T12:00:00')-new Date(isoToday()+'T12:00:00'))/86400000);el('examFocusDate').textContent=(e.persianDate||shamsiDate(e.isoDate,true))+' • '+faNum(Math.max(0,days))+' روز مانده';el('examReadiness').textContent=faNum(e.readiness||0)+'%';box.onclick=function(){openExam(e);};}
function examReasonText(d){var map={ready:'آماده شروع',resume:'آزمون در حال اجراست',not_open:'هنوز زمان آزمون نرسیده',closed:'زمان آزمون تمام شده',attempt_limit:'تلاش مجاز استفاده شده',retry_pending:'درخواست تلاش مجدد در حال بررسی است',no_questions:'مشاور هنوز سؤال‌ها را آماده نکرده',not_published:'هنوز منتشر نشده',cancelled:'آزمون لغو شده',completed:'آزمون بسته شده'};return map[d&&d.reason]||'اطلاعات آزمون';}
function examActionLabel(d){if(!d)return'مشاهده';if(d.reason==='resume')return'ادامه آزمون';if(d.canStart)return'شروع آزمون';if(d.reason==='attempt_limit')return'درخواست تلاش مجدد';return'جزئیات آزمون';}
function clearExamRefresh(){if(state.examRefreshTimer){clearTimeout(state.examRefreshTimer);state.examRefreshTimer=null;}}
function scheduleExamRefresh(exams){clearExamRefresh();var nowMs=Date.now(),next=0,list=exams||state.exams||[];for(var i=0;i<list.length;i++){var e=list[i],times=[e.openAt,e.closeAt];for(var j=0;j<times.length;j++){if(!times[j])continue;var ms=new Date(times[j]).getTime();if(ms>nowMs+100&&!isNaN(ms)&&(next===0||ms<next))next=ms;}}if(next){var delay=Math.max(250,Math.min(2147480000,next-nowMs+350));state.examRefreshTimer=setTimeout(function(){state.examRefreshTimer=null;if(state.authStatus==='authenticated')loadExams();},delay);}}
function loadExams(){api('GET','/exams',null,function(err,data){if(err)return toast(err.message,'error');state.exams=data||[];scheduleExamRefresh(state.exams);var box=el('examList'),h='';if(!state.exams.length)h='<div class="empty-card">آزمونی ثبت نشده است.</div>';for(var i=0;i<state.exams.length;i++){var e=state.exams[i],d=e.delivery||{},pct=0;h+='<article class="exam-card exam-delivery-card" data-exam="'+esc(e.id)+'"><div class="exam-card-head"><div><div class="eyebrow">'+esc(e.persianDate||shamsiDate(e.isoDate,true))+'</div><h3>'+esc(e.title)+'</h3><p>'+esc(examReasonText(d))+'</p></div><div class="readiness"><strong>…</strong><span>آمادگی</span></div></div><div class="exam-mini-stats"><span><small>تلاش</small><strong>'+faNum(d.attemptsUsed||0)+'/'+faNum(d.allowedAttempts||e.maxAttempts||1)+'</strong></span><span><small>زمان</small><strong>'+faNum(e.durationMinutes||120)+' دقیقه</strong></span><span><small>سؤال</small><strong>'+faNum(d.questionCount||0)+'</strong></span></div><div class="exam-window-student">'+icon(d.canStart||d.reason==='resume'?'target':'lock-exam')+'<span>'+esc(shortDateTime(e.openAt))+' تا '+esc(shortDateTime(e.closeAt))+'</span></div><button class="btn '+(d.canStart||d.reason==='resume'?'primary':'soft')+' full exam-open-button">'+esc(examActionLabel(d))+'</button></article>';}box.innerHTML=h;var cards=qa('[data-exam]',box);for(i=0;i<cards.length;i++)(function(card){var id=card.getAttribute('data-exam');api('GET','/exams/'+id+'/progress',null,function(er,p){if(!er){q('.readiness strong',card).textContent=faNum(p.readiness)+'%';q('.exam-open-button',card).textContent=examActionLabel(p.delivery||{});card.onclick=function(){openExam(p);};}});})(cards[i]);});}
function openExam(e){api('GET','/exams/'+e.id+'/progress',null,function(err,p){if(err)return toast(err.message,'error');var d=p.delivery||{};if(d.reason==='not_open'&&p.openAt){clearExamRefresh();var waitMs=new Date(p.openAt).getTime()-Date.now()+350;if(waitMs>0)state.examRefreshTimer=setTimeout(function(){state.examRefreshTimer=null;if(!el('examModal').classList.contains('hidden'))openExam({id:p.id});else loadExams();},Math.min(2147480000,waitMs));}var h='<div class="exam-modal-hero"><div><span class="eyebrow">'+esc(p.persianDate||shamsiDate(p.isoDate,true))+'</span><h3>'+esc(p.title)+'</h3><p>'+esc(p.instructions||p.note||'بودجه‌بندی و زمان آزمون را قبل از شروع بررسی کن.')+'</p></div><div class="readiness"><strong>'+faNum(p.readiness)+'%</strong><span>آمادگی</span></div></div><div class="exam-delivery-panel"><div class="exam-delivery-status"><strong>'+esc(examReasonText(d))+'</strong><small>'+esc(shortDateTime(p.openAt))+' تا '+esc(shortDateTime(p.closeAt))+'</small></div><div class="exam-mini-stats"><span><small>تلاش مصرف‌شده</small><strong>'+faNum(d.attemptsUsed||0)+'</strong></span><span><small>تلاش مجاز</small><strong>'+faNum(d.allowedAttempts||p.maxAttempts||1)+'</strong></span><span><small>مدت</small><strong>'+faNum(p.durationMinutes||120)+' دقیقه</strong></span></div>';
    if(d.canStart||d.reason==='resume')h+='<button id="examStartBtn" class="btn primary full exam-start">'+(d.reason==='resume'?'ادامه آزمون':'شروع آزمون')+'</button><p class="exam-warning">پس از شروع، زمان آزمون ادامه پیدا می‌کند؛ بستن پنجره زمان را متوقف نمی‌کند.</p>';
    else if(d.reason==='attempt_limit')h+='<label class="block-label">پیام برای مشاور<textarea id="examRetryMessage" rows="2" placeholder="چرا به یک تلاش دیگر نیاز داری؟"></textarea></label><button id="examRetryBtn" class="btn soft full">'+icon('retry')+' درخواست یک تلاش دیگر</button>';
    else if(d.reason==='retry_pending')h+='<div class="exam-pending">'+icon('retry')+' درخواست تلاش مجدد ارسال شده و منتظر تصمیم مشاور است.</div>';
    h+='</div><div class="syllabus-section"><h4>بودجه و وضعیت آمادگی</h4>';
    for(var i=0;i<p.syllabus.length;i++){var x=p.syllabus[i];h+='<div class="syllabus-item"><div class="syllabus-item-head"><div><strong>'+esc(x.subject)+'</strong><p>'+esc(x.description)+'</p></div><select data-syllabus="'+esc(x.id)+'"><option value="unread"'+(x.status==='unread'?' selected':'')+'>نخوانده</option><option value="read"'+(x.status==='read'?' selected':'')+'>خوانده</option><option value="tested"'+(x.status==='tested'?' selected':'')+'>تست زده</option><option value="review"'+(x.status==='review'?' selected':'')+'>نیازمند مرور</option><option value="mastered"'+(x.status==='mastered'?' selected':'')+'>مسلط</option></select></div></div>';}
    h+='</div>';el('examModalBody').innerHTML=h;openModal('examModal');if(el('examStartBtn'))el('examStartBtn').onclick=function(){startExam(p.id,this);};if(el('examRetryBtn'))el('examRetryBtn').onclick=function(){requestExamRetry(p.id,this);};var sels=qa('[data-syllabus]',el('examModalBody'));for(i=0;i<sels.length;i++)sels[i].onchange=function(){var id=this.getAttribute('data-syllabus'),v=this.value;api('PUT','/syllabus/'+id+'/progress',{status:v,accuracy:0,note:''},function(er){if(er)return toast(er.message,'error');toast('وضعیت ذخیره شد');loadReviews();});};});}
function startExam(id,btn){if(!id||state.quizSubmitting)return;setButtonBusy(btn,true);api('POST','/exams/'+encodeURIComponent(id)+'/start',{deviceLabel:deviceLabel()},function(err,data){setButtonBusy(btn,false);if(err){if(err.code==='EXAM_NOT_AVAILABLE'||err.code==='ATTEMPT_LIMIT')loadExams();return toast(err.message,'error');}state.currentExamId=id;state.currentExamCloseAt=data&&data.exam?data.exam.closeAt:null;beginQuizRun(data);});}
