function renderMistakes(){var counts={},h='';for(var i=0;i<state.mistakes.length;i++){var m=state.mistakes[i],r=m.errorReason||'دسته‌بندی نشده';counts[r]=(counts[r]||0)+1;h+='<div class="mistake-card"><strong>'+esc((m.subject?m.subject+' — ':'')+(m.quizTitle||''))+'</strong><p>'+esc(m.question||'')+'</p><select data-mistake="'+esc(m.id)+'"><option value="">دلیل خطا...</option>';for(var j=0;j<mistakeReasons.length;j++)h+='<option'+(m.errorReason===mistakeReasons[j]?' selected':'')+'>'+esc(mistakeReasons[j])+'</option>';h+='</select></div>';}var sum='';for(var k in counts)if(Object.prototype.hasOwnProperty.call(counts,k))sum+='<span>'+esc(k)+': '+faNum(counts[k])+'</span>';el('mistakeSummary').innerHTML=sum||'<span>هنوز خطای ثبت‌شده‌ای نیست.</span>';el('mistakeList').innerHTML=h;var sels=qa('[data-mistake]');for(i=0;i<sels.length;i++)sels[i].onchange=function(){var id=this.getAttribute('data-mistake'),v=this.value;api('PATCH','/mistakes/'+id,{errorReason:v},function(err){if(err)toast(err.message);else toast('دلیل خطا ذخیره شد');});};}
function loadSchedule(date){state.scheduleDate=date;el('scheduleDate').value=date;if(el('schedulePersianDate'))el('schedulePersianDate').textContent=shamsiDate(date,true);api('GET','/plans?date='+date,null,function(err,p){if(err)return toast(err.message);if(p&&p.persianDate&&el('schedulePersianDate'))el('schedulePersianDate').textContent=p.persianDate;renderScheduleMotivation(p);renderTimeline(p&&p.tasks?p.tasks:[],'scheduleDay');});}
