function loadNotifications(){api('GET','/notifications',null,function(err,data){if(err)return toast(err.message,'error');var list=data||[],h='',unread=0;for(var i=0;i<list.length;i++){var n=list[i];if(!n.isRead)unread++;h+='<button class="notification-item '+(!n.isRead?'unread':'')+'" data-notification="'+esc(n.id)+'"><span class="notification-dot"></span><span class="notification-copy"><strong>'+esc(n.title)+'</strong><p>'+esc(n.body)+'</p><small>'+esc(shortDateTime(n.createdAt||''))+'</small></span>'+(!n.isRead?'<b>جدید</b>':'')+'</button>';}el('notificationsList').innerHTML=h||'<div class="empty-card">پیام جدیدی نداری.</div>';el('notificationUnreadText').textContent=faNum(unread);el('notificationBadge').textContent=faNum(unread);el('notificationBadge').className=unread?'badge':'badge hidden';openModal('notificationsModal');var bs=qa('[data-notification]',el('notificationsList'));for(i=0;i<bs.length;i++)bs[i].onclick=function(){var id=this.getAttribute('data-notification'),row=this;if(!row.classList.contains('unread'))return;api('PUT','/notifications/'+encodeURIComponent(id)+'/read',{},function(er){if(er)return toast(er.message,'error');row.classList.remove('unread');loadNotifications();loadDashboard();});};});}
