function quizDraftKey(){return state.quizRunId?'moshaver_quiz_draft:'+state.quizRunId:'';}
function saveQuizDraft(){var k=quizDraftKey();if(!k)return;try{localStorage.setItem(k,JSON.stringify({answers:state.quizAnswers,index:state.quizIndex}));}catch(e){}}
function loadQuizDraft(){var k=quizDraftKey();if(!k)return;try{var d=JSON.parse(localStorage.getItem(k)||'null');if(d){state.quizAnswers=d.answers||{};state.quizIndex=Math.max(0,Number(d.index||0));}}catch(e){}}
function clearQuizDraft(){var k=quizDraftKey();if(!k)return;try{localStorage.removeItem(k);}catch(e){}}
function beginQuizRun(data){state.quiz=data.quiz;state.quizRunId=data.runId;state.quizIndex=0;state.quizAnswers={};state.quizStartedAt=data.startedAt;state.busyQuiz=true;state.quizSubmitting=false;loadQuizDraft();sendPresence();closeModals();openModal('quizModal');startQuizTimer();renderQuiz();}
function startQuiz(id){if(!id)return;api('POST','/quizzes/'+id+'/start',{deviceLabel:deviceLabel()},function(err,data){if(err)return toast(err.message,'error');state.currentExamId=data.quiz&&data.quiz.examId?data.quiz.examId:null;state.currentExamCloseAt=null;beginQuizRun(data);});}
function startQuizTimer(){stopQuizTimer();updateQuizTimer();state.quizTimer=setInterval(updateQuizTimer,1000);}
function stopQuizTimer(){if(state.quizTimer)clearInterval(state.quizTimer);state.quizTimer=null;}
function remainingQuizSeconds(){if(!state.quiz||!state.quizStartedAt)return 0;var total=Math.max(1,Number(state.quiz.durationMinutes||20))*60,elapsed=Math.max(0,Math.floor((Date.now()-new Date(state.quizStartedAt).getTime())/1000)),left=Math.max(0,total-elapsed);if(state.currentExamCloseAt){var closeLeft=Math.max(0,Math.floor((new Date(state.currentExamCloseAt).getTime()-Date.now())/1000));left=Math.min(left,closeLeft);}return left;}
function updateQuizTimer(){var sec=remainingQuizSeconds(),node=el('quizCountdown');if(node){var m=Math.floor(sec/60),s=sec%60;node.textContent=faNum(('0'+m).slice(-2)+':'+('0'+s).slice(-2));node.className='quiz-countdown '+(sec<=300?'danger':'');}if(sec<=0&&state.busyQuiz&&!state.quizSubmitting)finishQuiz(true);}
function renderQuiz(){var qz=state.quiz;if(!qz)return;var qs=qz.questions||[],idx=Math.min(state.quizIndex,Math.max(0,qs.length-1)),qst=qs[idx];state.quizIndex=idx;if(!qst){finishQuiz();return;}var letters=['a','b','c','d'],h='<div class="quiz-topline"><div class="eyebrow">'+esc(qz.title)+' • سؤال '+faNum(idx+1)+' از '+faNum(qs.length)+'</div><strong id="quizCountdown" class="quiz-countdown">--:--</strong></div><div class="quiz-progress"><i style="width:'+Math.round((idx+1)*100/qs.length)+'%"></i></div><div class="quiz-question">'+esc(qst.question)+'</div>';for(var i=0;i<4;i++)h+='<button class="quiz-option '+(state.quizAnswers[qst.id]===letters[i]?'selected':'')+'" data-option="'+letters[i]+'"><span>'+faNum(i+1)+'</span>'+esc(qst.options[i])+'</button>';h+='<div class="quiz-answer-state">'+faNum(Object.keys(state.quizAnswers).length)+' از '+faNum(qs.length)+' پاسخ داده شده</div><div class="quiz-footer"><button id="quizPrev" class="btn soft"'+(idx===0?' disabled':'')+'>قبلی</button><button id="quizNext" class="btn primary">'+(idx===qs.length-1?'ثبت نهایی':'بعدی')+'</button></div>';el('quizBody').innerHTML=h;updateQuizTimer();var opts=qa('[data-option]',el('quizBody'));for(i=0;i<opts.length;i++)opts[i].onclick=function(){state.quizAnswers[qst.id]=this.getAttribute('data-option');saveQuizDraft();renderQuiz();};el('quizPrev').onclick=function(){if(state.quizIndex>0){state.quizIndex--;saveQuizDraft();renderQuiz();}};el('quizNext').onclick=function(){if(state.quizIndex<qs.length-1){state.quizIndex++;saveQuizDraft();renderQuiz();}else{var blank=qs.length-Object.keys(state.quizAnswers).length;if(blank>0&&!confirm(faNum(blank)+' سؤال بدون پاسخ است. آزمون ثبت شود؟'))return;finishQuiz();}};}
function finishQuiz(auto){if(!state.quiz||!state.quizRunId||state.quizSubmitting)return;state.quizSubmitting=true;var answers=[],qs=state.quiz.questions||[];for(var i=0;i<qs.length;i++)answers.push({questionId:qs[i].id,selectedOption:state.quizAnswers[qs[i].id]||null,errorReason:''});api('POST','/quizzes/'+state.quiz.id+'/attempts',{runId:state.quizRunId,answers:answers},function(err,result){state.quizSubmitting=false;if(err)return toast(err.message,'error');stopQuizTimer();clearQuizDraft();state.busyQuiz=false;state.quizRunId=null;sendPresence();el('quizBody').innerHTML='<div class="quiz-result"><div class="readiness"><strong>'+faNum(result.percent)+'%</strong><span>نتیجه</span></div><h3>'+(auto?'زمان تمام شد؛ آزمون ثبت شد':'آزمون ثبت شد')+'</h3><p class="muted">'+faNum(result.correct)+' درست • '+faNum(result.wrong)+' غلط • '+faNum(result.blank)+' نزده • '+faNum(Math.round((result.durationSeconds||0)/60))+' دقیقه</p><button id="quizResultClose" class="btn primary full">بستن آزمون و برگشت به برنامه</button></div>';el('quizResultClose').onclick=function(){closeModals();state.quiz=null;state.currentExamId=null;state.currentExamCloseAt=null;loadDashboard();loadProgress();loadExams();};});}
function cancelQuiz(){if(!state.busyQuiz){closeModals();return;}var isExam=!!(state.quiz&&state.quiz.examId);if(isExam){if(confirm('از صفحه آزمون خارج شوی؟ زمان آزمون ادامه دارد و دوباره می‌توانی همین تلاش را ادامه بدهی.')){saveQuizDraft();stopQuizTimer();state.busyQuiz=false;state.quiz=null;state.currentExamId=null;state.currentExamCloseAt=null;sendPresence();closeModals();loadExams();}return;}if(confirm('آزمونک را بدون ثبت ببندی؟')){record('quiz.cancelled','quiz',state.quiz?state.quiz.id:'',{});clearQuizDraft();stopQuizTimer();state.busyQuiz=false;state.quiz=null;state.quizRunId=null;state.sessionActionBusy=false;state.currentExamId=null;state.currentExamCloseAt=null;clearExamRefresh();sendPresence();closeModals();}}
function chatActive(){return el('view-chat')&&el('view-chat').classList.contains('active');}
function setChatBadge(n){state.chatUnread=Math.max(0,Number(n||0));var b=el('chatNavBadge');if(!b)return;b.textContent=faNum(state.chatUnread);b.className=state.chatUnread?'badge nav-badge':'badge nav-badge hidden';}
function chatTime(v){try{var d=new Date(v);return('0'+d.getHours()).slice(-2)+':'+('0'+d.getMinutes()).slice(-2);}catch(e){return'';}}
function scrollChatBottom(){var box=el('chatMessages');if(!box)return;box.scrollTop=box.scrollHeight;setTimeout(function(){box.scrollTop=box.scrollHeight;},30);}
function renderChat(){var box=el('chatMessages');if(!box)return;var list=state.chatMessages||[],h='',lastDay='';if(!list.length)h='<div class="chat-empty-friendly">'+icon('advisor')+'<strong>هنوز پیامی نیست</strong><p>مثل یک گفت‌وگوی معمولی، پیام کوتاهت را برای مشاور بفرست.</p></div>';for(var i=0;i<list.length;i++){var m=list[i],mine=state.me&&m.senderUserId===state.me.id,day=String(m.createdAt||'').slice(0,10);if(day!==lastDay){lastDay=day;h+='<div class="chat-day-separator"><span>'+esc(chatDayLabel(day))+'</span></div>';}h+='<div class="message-row '+(mine?'mine':'theirs')+'">'+(!mine?'<span class="message-avatar">م</span>':'')+'<div class="message-bubble"><p>'+esc(m.deletedAt?'پیام حذف شده':m.text)+'</p><div class="message-meta"><span>'+faNum(chatTime(m.createdAt))+'</span>'+(mine?'<span class="message-seen">'+(m.seen?'✓✓':'✓')+'</span>':'')+'</div></div></div>';}box.innerHTML=h;scrollChatBottom();}
function markChatRead(){if(!state.chatConversation)return;api('POST','/chat/conversations/'+encodeURIComponent(state.chatConversation.id)+'/read',{},function(err){if(!err)setChatBadge(0);});}
function loadChat(mark){api('GET','/chat/conversation',null,function(err,c){if(err)return toast(err.message);state.chatConversation=c;el('advisorName').textContent=c.advisor&&c.advisor.name?c.advisor.name:'مشاور';setChatBadge(c.unread||state.chatUnread);api('GET','/chat/conversations/'+encodeURIComponent(c.id)+'/messages?limit=80',null,function(er,d){if(er)return toast(er.message);state.chatMessages=d.messages||[];renderChat();if(mark||chatActive())markChatRead();});});}
function sendChat(){var input=el('chatInput'),text=String(input.value||'').trim();if(!text||!state.chatConversation||state.chatSending)return;if(text.length>3000)return toast('پیام خیلی طولانی است.','error');state.chatSending=true;setButtonBusy(el('studentChatSend'),true);api('POST','/chat/conversations/'+encodeURIComponent(state.chatConversation.id)+'/messages',{text:text},function(err,item){state.chatSending=false;setButtonBusy(el('studentChatSend'),false);if(err)return toast(err.message,'error');input.value='';autoGrow(input);state.chatMessages.push(item);renderChat();});}
function disconnectEvents(){if(state.eventSource){try{state.eventSource.close();}catch(e){}state.eventSource=null;}if(state.chatPoll){clearInterval(state.chatPoll);state.chatPoll=null;}}
function realtimeEvent(type,data){if(type==='chat.message.created'){if(data&&state.chatConversation&&data.conversationId===state.chatConversation.id){loadChat(chatActive());}else setChatBadge(state.chatUnread+1);if(!chatActive())toast('پیام جدید از مشاور');return;}if(type==='chat.messages.read'){if(chatActive())loadChat(false);return;}if(type==='plan.published'||type==='plan.updated'){toast('برنامه توسط مشاور به‌روزرسانی شد');loadDashboard();if(el('view-schedule').classList.contains('active'))loadSchedule(state.scheduleDate||isoToday());return;}if(type==='exam.updated'||type==='exam.retry_reviewed'){toast(type==='exam.retry_reviewed'?'وضعیت درخواست آزمون به‌روزرسانی شد':'آزمون توسط مشاور به‌روزرسانی شد');if(el('view-exams').classList.contains('active'))loadExams();loadDashboard();return;}if(type==='advisor.comment.created'){toast('پیام جدید مشاور برای یکی از فعالیت‌ها');return;}if(type==='notification.created'){var b=el('notificationBadge'),n=state.dashboard?Number(state.dashboard.unreadNotifications||0):0;b.textContent=faNum(n+1);b.className='badge';toast(data&&data.title?data.title:'اعلان جدید');return;}if(type==='review.created')loadReviews();}
