function openPassword(){openModal('passwordModal');}
function changePassword(){var a=el('studentNewPassword').value,b=el('studentNewPassword2').value;if(a!==b)return toast('تکرار رمز با رمز جدید یکسان نیست.');if(a.length<12)return toast('رمز جدید باید حداقل ۱۲ نویسه باشد.');api('POST','/auth/change-password',{currentPassword:el('studentCurrentPassword').value,newPassword:a},function(err){if(err)return toast(err.message);closeModals();el('studentCurrentPassword').value='';el('studentNewPassword').value='';el('studentNewPassword2').value='';toast('رمز تغییر کرد و نشست‌های دیگر بسته شدند.');});}
