function logout(){
  if(state.authStatus==='logging-out'||state.authStatus==='anonymous')return;
  state.authStatus='logging-out';
  state.authEpoch++;state.bootEpoch++;
  if(state.loginRequest){try{state.loginRequest.abort();}catch(e){}state.loginRequest=null;}
  if(state.startupAuthRequest){try{state.startupAuthRequest.abort();}catch(e){}state.startupAuthRequest=null;}
  API.abortAll();stopPresence();disconnectEvents();stopSessionClock();
  setPendingLogout(true);
  API.request('POST','/auth/logout',{},function(err){
    if(err&&err.status===0){finishLocalLogout('از برنامه خارج شدی. خروج سرور به محض برگشت اینترنت تکمیل می‌شود.',true,false);return;}
    finishLocalLogout('با موفقیت خارج شدید.',false,false);
  },{suppressAuthFailure:true,noCsrfRetry:true});
}
function bindActions(){el('loginForm').onsubmit=function(e){
  e.preventDefault();
  if(state.authStatus==='logging-in')return;
  cancelStartupAuth();
  if(state.loginRequest){try{state.loginRequest.abort();}catch(ex){}state.loginRequest=null;}
  el('loginError').className='form-error hidden';
  var btn=q('#loginForm button[type="submit"]'),btnLabel=btn?btn.textContent:'';if(btn){btn.disabled=true;btn.textContent='در حال ورود…';}
  state.authStatus='logging-in';
  var loginEpoch=++state.authEpoch;
  state.loginRequest=API.request('POST','/auth/login',{username:el('loginUsername').value,password:el('loginPassword').value},function(err,data){
    state.loginRequest=null;if(btn){btn.disabled=false;btn.textContent=btnLabel||'ورود به برنامه';}
    if(loginEpoch!==state.authEpoch)return;
    if(err){state.authStatus='anonymous';el('loginError').textContent=err.message;el('loginError').className='form-error';return;}
    if(!data||!data.user||data.user.role!=='student'){if(data&&data.csrfToken)API.setCsrf(data.csrfToken);clearWrongRoleSession('این حساب دانش‌آموز نیست.');return;}
    setPendingLogout(false);API.setCsrf(data.csrfToken||'');state.me=data.user;state.authStatus='authenticated';el('loginPassword').value='';
    broadcastAuth('login');bootAuthenticated();
  },{suppressAuthFailure:true});
};el('startNowBtn').onclick=function(){if(state.currentTask&&state.currentTask.type==='exam'&&state.currentTask.examId){openExam({id:state.currentTask.examId});return;}if(state.activeSession)finishStudy();else if(state.currentTask)startStudy(state.currentTask);};el('openNowBtn').onclick=function(){if(state.currentTask&&state.currentTask.type==='exam'&&state.currentTask.examId)openExam({id:state.currentTask.examId});else openTask(state.currentTask);};el('recoveryQuickBtn').onclick=openRecovery;el('recoveryBtn').onclick=openRecovery;el('submitRecoveryBtn').onclick=submitRecovery;el('submitIssueBtn').onclick=submitIssue;el('reportBtn').onclick=openReport;el('submitReportBtn').onclick=submitReport;el('notificationBtn').onclick=loadNotifications;el('notificationsMenuBtn').onclick=loadNotifications;el('markAllNotifications').onclick=function(){api('PUT','/notifications/read-all',{},function(err){if(err)return toast(err.message,'error');toast('همه اعلان‌ها خوانده شد');loadNotifications();loadDashboard();});};el('passwordBtn').onclick=openPassword;el('studentSavePassword').onclick=changePassword;el('themeBtn').onclick=toggleTheme;el('progressBtn').onclick=function(){switchView('progress');};el('logoutBtn').onclick=logout;el('scheduleTodayBtn').onclick=function(){loadSchedule(isoToday());};el('schedulePrev').onclick=function(){loadSchedule(shiftDate(state.scheduleDate||isoToday(),-1));};el('scheduleNext').onclick=function(){loadSchedule(shiftDate(state.scheduleDate||isoToday(),1));};el('scheduleDate').onchange=function(){if(this.value)loadSchedule(this.value);};if(el('schedulePickBtn'))el('schedulePickBtn').onclick=function(){var input=el('scheduleDate');try{if(input.showPicker)input.showPicker();else input.click();}catch(e){input.click();}};el('focusInput').oninput=syncOutputs;el('fatigueInput').oninput=syncOutputs;el('motivationInput').oninput=syncOutputs;el('quizCloseBtn').onclick=cancelQuiz;el('focusBackBtn').onclick=hideFocus;el('focusFinishBtn').onclick=function(){finishStudy();};el('chatForm').onsubmit=function(e){e.preventDefault();sendChat();};var cq=qa('[data-student-chat-quick]');for(var i=0;i<cq.length;i++)cq[i].onclick=function(){el('chatInput').value=this.getAttribute('data-student-chat-quick');autoGrow(el('chatInput'));el('chatInput').focus();};el('chatInput').oninput=function(){autoGrow(this);};}
function bootAuthenticated(){
  if(state.authStatus!=='authenticated'||!state.me)return;
  state.bootEpoch++;
  stopPresence();disconnectEvents();
  showApp();state.scheduleDate=isoToday();
  loadDashboard();connectEvents();loadChat(false);flushQueue();
}
function syncVisible(){
  if(state.authStatus!=='authenticated'||!state.me||document.hidden)return;
  if(Date.now()-state.lastSyncAt<15000)return;
  API.refreshCsrf(function(err){if(err)return;loadDashboard();if(chatActive())loadChat(false);});
}
function syncAuthSignal(ev){
  if(!ev||ev.key!==AUTH_SIGNAL_KEY||!ev.newValue)return;
  var data=null;try{data=JSON.parse(ev.newValue);}catch(e){}
  if(!data)return;
  if(data.kind==='logout'){
    if(state.authStatus!=='anonymous')finishLocalLogout('نشست در تب دیگری خارج شد.',false,true);
    return;
  }
  if(data.kind==='login'&&state.authStatus!=='logging-in'&&state.authStatus!=='logging-out'){
    restoreStudentAuth();
  }
}
function restoreStudentAuth(){if(state.authRetryTimer){clearTimeout(state.authRetryTimer);state.authRetryTimer=null;}var btn=q('#loginForm button[type="submit"]');if(btn){btn.disabled=true;btn.textContent='در حال بازیابی نشست…';}var er=el('loginError');if(er){er.textContent='در حال بررسی نشست امن…';er.className='form-error auth-checking';}loadMe(function(err){if(err){if(err.handled)return;if(err.status===401){if(btn){btn.disabled=false;btn.textContent='ورود به برنامه';}showLogin();return;}state.authStatus='checking';if(er){er.textContent='ارتباط موقتاً قطع است؛ نشست شما حفظ شده و دوباره تلاش می‌کنیم…';er.className='form-error auth-checking';}state.authRetryTimer=setTimeout(restoreStudentAuth,1800);return;}if(btn){btn.disabled=false;btn.textContent='ورود به برنامه';}bootAuthenticated();});}
function init(){
  bindClosers();bindNav();bindActions();applyTheme();
  API.setAuthFailureHandler(handleAuthFailure);
  el('appVersion').textContent=(global.APP_CONFIG&&global.APP_CONFIG.APP_VERSION)||'1.4.2';
  setInterval(function(){if(!el('appScreen').classList.contains('hidden'))renderCurrent();},30000);
  window.addEventListener('online',function(){el('offlineBar').className='offline-bar hidden';if(hasPendingLogout()){flushPendingLogout(function(err){if(!err&&state.authStatus==='anonymous')showLogin('خروج سرور هم تکمیل شد.');});return;}flushQueue();syncVisible();});
  window.addEventListener('offline',function(){el('offlineBar').className='offline-bar';setSync('آفلاین');});
  document.addEventListener('visibilitychange',function(){if(!document.hidden)syncVisible();});
  window.addEventListener('pageshow',syncVisible);
  window.addEventListener('storage',syncAuthSignal);
  if(navigator.onLine===false)el('offlineBar').className='offline-bar';
  if(hasPendingLogout()){
    state.authStatus='logging-out';
    flushPendingLogout(function(err){state.authStatus='anonymous';if(err)showLogin('خروج قبلی هنوز منتظر اتصال اینترنت است.');else showLogin();});
    return;
  }
  loadMe(function(err){if(err){if(!err.handled)showLogin();return;}bootAuthenticated();});
}
